static void program_sequence(struct radeon_device *rdev, const u32 *registers, u32 array_size)
{
	u32 tmp, reg, and_mask, or_mask;
	u32 i;

	if (array_size % 3)
		return;
	for (i = 0; i < array_size; i += 3) {
		reg = registers[i + 0];
		and_mask = registers[i + 1];
		or_mask = registers[i + 2];
		if (and_mask == 0xffffffff) {
			tmp = or_mask;
		} else {
			tmp = RREG32(reg);
			tmp &= ~and_mask;
			tmp |= or_mask;
		}
		WREG32(reg, tmp);
	}
}

#define SEQ(t) program_sequence(rdev, t, (u32)(sizeof(t) / sizeof(t[0])))

void evergreen_init_golden_registers(struct radeon_device *rdev)
{
	switch (rdev->family) {
	case CHIP_CEDAR:
		SEQ(cedar_golden_registers);
		SEQ(evergreen_golden_registers2);
		SEQ(cedar_mgcg_init);
		break;
	case CHIP_CAICOS:
		SEQ(caicos_golden_registers);
		break;
	default:
		break;
	}
}
